fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let w = width as usize;
    let n = orig.len();

    // If already wide enough, return unchanged.
    if n >= w {
        return orig;
    }

    // Need left padding.
    let pad = w - n;
    let mut res = Vec::with_capacity(w);
    res.extend(std::iter::repeat(fillchar).take(pad));
    res.extend(orig);
    res
}

